<#
.SYNOPSIS
  Read the defensive side of the attack pass from the DC and an endpoint.
.DESCRIPTION
  Pulls the event-log evidence the attacks generate (failed logons, lockouts,
  Kerberos ticket requests) and confirms the key hardening controls are live.
.NOTES
  Lab: corp.local  (Windows Server 2025 Active Directory lab)
  Run the event-log section on CORP-DC01, the control checks on a managed endpoint.
#>

Write-Host "== Event-log evidence (run on CORP-DC01) =="

# Failed logons generated by the spray
Get-WinEvent -FilterHashtable @{LogName='Security'; Id=4625} -MaxEvents 50 |
    Select-Object TimeCreated, @{n='Account';e={$_.Properties[5].Value}} | Format-Table -Auto

# Account lockouts (the spray tripping GPO-PasswordPolicy)
Get-WinEvent -FilterHashtable @{LogName='Security'; Id=4740} -ErrorAction SilentlyContinue |
    Select-Object TimeCreated, @{n='LockedAccount';e={$_.Properties[0].Value}} | Format-Table -Auto

# Kerberos service-ticket requests (the Kerberoast attempt)
Get-WinEvent -FilterHashtable @{LogName='Security'; Id=4769} -MaxEvents 50 |
    Select-Object TimeCreated, @{n='Service';e={$_.Properties[2].Value}} | Format-Table -Auto

Write-Host "`n== Control checks (run on a managed endpoint) =="

# LSA protection should be on (blocks LSASS dumping)
(Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\Lsa" -Name RunAsPPL -ErrorAction SilentlyContinue).RunAsPPL

# No cached logons (blocks offline cached-credential reuse)
(Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon" -Name CachedLogonsCount -ErrorAction SilentlyContinue).CachedLogonsCount

# SMB signing required (added after the attack pass found it missing)
(Get-ItemProperty "HKLM:\System\CurrentControlSet\Services\LanmanServer\Parameters" -Name RequireSecuritySignature -ErrorAction SilentlyContinue).RequireSecuritySignature

# LLMNR turned off (added after Responder succeeded)
(Get-ItemProperty "HKLM:\Software\Policies\Microsoft\Windows NT\DNSClient" -Name EnableMulticast -ErrorAction SilentlyContinue).EnableMulticast
